import sys, os, json, csv, gzip, io, re, glob
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def epoch(dt):
    return int(dt.timestamp())


def local_to_epoch(naive, tz, fold=0):
    return epoch(naive.replace(tzinfo=tz, fold=fold))


def std_offset(tz):
    # standard offset in seconds (use January/July, pick the smaller dst-free one)
    best = None
    for m in (1, 7):
        d = datetime(2026, m, 1, tzinfo=tz)
        if not d.dst():
            return int(d.utcoffset().total_seconds())
        o = int((d.utcoffset() - d.dst()).total_seconds())
        best = o
    return best


def parse_abbr(path, tz, out):
    header = None
    for line in lines_of(read_text(path)):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = {n: i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]]
        t = g('Time').upper()
        m = re.match(r'(\d+):(\d+):(\d+)\s*([AP]M)?$', t)
        h, mi, s = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if m.group(4):
            h = h % 12 + (12 if m.group(4) == 'PM' else 0)
        mo, d, y = g('Date').split('/')
        naive = datetime(int(y), int(mo), int(d), h, mi, s)
        fold = 0 if g('Zone').upper().endswith('DT') else 1
        out.append((g('Record'), g('Badge'), g('Punch').upper(), local_to_epoch(naive, tz, fold)))


def parse_epoch(path, tz, out):
    schema = 1
    for line in lines_of(read_text(path)):
        o = json.loads(line)
        if o.get('heartbeat'):
            continue
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if schema == 2:
            pid, emp, d, ts = o['punch_id'], o['employee'], o['direction'], int(o['epoch_ms']) // 1000
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            ts = int(o['ts']) if 'ts' in o else int(o['ts_ms']) // 1000
        out.append((str(pid), emp, d.upper(), ts))


def parse_offset(path, tz, out):
    rd = csv.reader(io.StringIO('\n'.join(lines_of(read_text(path)))), delimiter=';')
    hdr = None
    for row in rd:
        if hdr is None:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        ev = row[hdr['event']]
        dt = datetime.fromisoformat(row[hdr['timestamp']].replace('Z', '+00:00'))
        out.append((row[hdr['punch_id']], row[hdr['employee']], 'IN' if ev == 'clock_in' else 'OUT', epoch(dt)))


def parse_legacy(path, tz, out):
    off = std_offset(tz)
    for line in read_text(path).replace('\r\n', '\n').split('\n'):
        if not line.strip():
            continue
        t = line[0]
        if t == 'H':
            s = line[13:18].strip()
            if s and s[0] in '+-' and len(s) == 5:
                v = (int(s[1:3]) * 3600 + int(s[3:5]) * 60)
                off = -v if s[0] == '-' else v
            else:
                off = std_offset(tz)
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            d = line[15]
            ts = line[16:30]
            naive = datetime.strptime(ts, '%Y%m%d%H%M%S')
            e = int(naive.replace(tzinfo=UTC).timestamp()) - off
            out.append((pid, 'E' + badge, 'IN' if d == 'I' else 'OUT', e))


def parse_de(path, tz, out):
    hdr = None
    for line in lines_of(read_text(path)):
        row = [c.strip() for c in line.split('\t')]
        if 'Ausweis' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        g = lambda n: row[hdr[n]]
        dd, mm, yy = g('Datum').split('.')
        hh, mi = g('Uhrzeit').split(':')[:2]
        naive = datetime(int(yy), int(mm), int(dd), int(hh), int(mi))
        fold = 0 if g('Zeitzone').upper() == 'MESZ' else 1
        out.append((g('Nr'), g('Ausweis'), 'IN' if g('Buchung') == 'K' else 'OUT', local_to_epoch(naive, tz, fold)))


def parse_localcsv(path, tz, out):
    rd = csv.reader(io.StringIO('\n'.join(lines_of(read_text(path)))))
    hdr = None
    for row in rd:
        if hdr is None:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        naive = datetime.strptime(row[hdr['local_time']].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((row[hdr['punch_ref']].strip(), row[hdr['employee_id']].strip(),
                    row[hdr['direction']].strip().upper(), local_to_epoch(naive, tz, 0)))


def parse_localjsonl(path, tz, out):
    for line in lines_of(read_text(path)):
        o = json.loads(line)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        pid = p['id']
        pid = str(int(pid)) if not isinstance(pid, str) or pid.strip().isdigit() else pid
        out.append((pid, p['badge'], p['type'].upper(), local_to_epoch(naive, tz, 0)))


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def read_csv(path):
    return list(csv.DictReader(io.StringIO('\n'.join(lines_of(read_text(path))))))


def main(inp, outpath):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00'))
    sites = {r['site'].strip(): r for r in read_csv(os.path.join(inp, 'sites.csv'))}
    tzs = {s: ZoneInfo(r['timezone'].strip()) for s, r in sites.items()}
    emps = read_csv(os.path.join(inp, 'employees.csv'))
    emp_home = {r['employee_id'].strip(): r['home_site'].strip() for r in emps}
    rates = {}
    for r in read_csv(os.path.join(inp, 'rates.csv')):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    punches = {}  # (site,id) -> [emp, dir, ts]
    ever = set()
    for site in sorted(sites):
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        fmt = sites[site]['format'].strip()
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                recs = []
                PARSERS[fmt](os.path.join(root, fn), tzs[site], recs)
                for pid, emp, dr, ts in recs:
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    # corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for fn in sorted(os.listdir(cdir)):
            p = os.path.join(cdir, fn)
            if os.path.isfile(p):
                corr.extend(read_csv(p))
    items = []
    for c in corr:
        ia = datetime.fromisoformat(c['issued_at'].strip().replace('Z', '+00:00'))
        if ia > cutoff:
            continue
        items.append((ia, c['correction_id'], c))
    items.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    for _, _, c in items:
        k = (c['site'].strip(), c['punch_id'].strip())
        a = c['action'].strip()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = epoch(datetime.fromisoformat(c['time'].strip().replace('Z', '+00:00')))
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [c['employee'].strip(), c['type'].strip().upper(),
                              epoch(datetime.fromisoformat(c['time'].strip().replace('Z', '+00:00')))]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emp_home:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, site):
        off = int(datetime.fromtimestamp(ts, tzs[site]).utcoffset().total_seconds())
        x = ts + off
        return (x + 180) // 360 * 360 - off

    homes = {e: tzs[emp_home[e]] for e in emp_home}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0)) for e in emp_home}
    offcache = {}

    def night_minutes(a, b, tz, key):
        n = 0
        t = a
        while t < b:
            ck = (key, t // 900)
            if ck not in offcache:
                offcache[ck] = int(datetime.fromtimestamp(t, tz).utcoffset().total_seconds())
            sec = (t + offcache[ck]) % 86400
            if sec < 21600 or sec >= 79200:
                n += 1
            t += 60
        return n

    def workday(ts, e):
        return datetime.fromtimestamp(ts, homes[e]).date()

    def inp_(d):
        return pstart <= d <= pend

    for e, pl in byemp.items():
        pl.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        for ts, _, site, pid, dr in pl:
            r = rnd(ts, site)
            if kept and kept[-1][4] == dr and ts - kept[-1][0] <= 300:
                if inp_(workday(r, e)):
                    exc['duplicates_dropped'] += 1
                continue
            kept.append((ts, r, site, pid, dr))
        shifts = []
        cur = None
        for ts, r, site, pid, dr in kept:
            if dr == 'IN':
                if cur is not None and inp_(workday(cur[1], e)):
                    exc['open_shifts'] += 1
                cur = (ts, r, site)
            else:
                if cur is not None and r - cur[1] <= 16 * 3600:
                    shifts.append((cur, r, site))
                    cur = None
                else:
                    if cur is not None:
                        if inp_(workday(cur[1], e)):
                            exc['open_shifts'] += 1
                        cur = None
                    if inp_(workday(r, e)):
                        exc['orphan_outs'] += 1
        if cur is not None and inp_(workday(cur[1], e)):
            exc['open_shifts'] += 1
        sl = []
        for (its, ir, isite), orr, osite in shifts:
            wd = workday(ir, e)
            if not inp_(wd):
                continue
            worked = max(0, (orr - ir) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(paid, night_minutes(ir, orr, tzs[isite], isite))
            sl.append((ir, wd, paid, night))
        sl.sort()
        daily = {}
        weekly = {}
        total = Decimal(0)
        R = res[e]
        for ir, wd, paid, night in sl:
            dused = daily.get(wd, 0)
            dot = max(0, dused + paid - 480) - max(0, dused - 480)
            daily[wd] = dused + paid
            nd = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wused = weekly.get(wk, 0)
            wot = max(0, wused + nd - 2400) - max(0, wused - 2400)
            weekly[wk] = wused + nd
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt in rates.get(e, []):
                if ef <= wd:
                    rate = rt
            if rate is None:
                rate = Decimal(0)
            total += rate * (Decimal(reg) + Decimal('1.5') * ot) / 60 + rate * Decimal('0.15') * night / 60
            R['shifts'] += 1
            R['paid_minutes'] += paid
            R['overtime_minutes'] += ot
            R['night_minutes'] += night
        R['gross'] = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0))
    out_e = {}
    for e in sorted(res):
        r = res[e]
        for k in tot:
            tot[k] += r[k]
        out_e[e] = dict(r, gross=format(r['gross'], '.2f'))
    tot['gross'] = format(tot['gross'], '.2f')
    with open(outpath, 'w') as f:
        json.dump(dict(period=dict(start=period['start'], end=period['end']), employees=out_e,
                       exceptions=exc, totals=tot), f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
